const wildlifeDialog=document.getElementById('wildlifeDialog'),wildlifeProfile=document.getElementById('wildlifeProfile');
document.querySelector('.wildlife-close').addEventListener('click',()=>wildlifeDialog.close());
animalGrid.addEventListener('click',event=>{const button=event.target.closest('[data-profile]');if(button)openWildlifeProfile(button.dataset.profile)});
function profileSafe(value,fallback='Not recorded'){return String(value||fallback).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function countryName(code){try{return new Intl.DisplayNames([navigator.language||'en'],{type:'region'}).of(code)||code}catch{return code}}
async function profileJson(url){const response=await fetch(url);if(!response.ok)throw new Error(`${response.status}`);return response.json()}
const PROFILE_MEDIA_CACHE='pocketbook-wildlife-media-v1',PROFILE_MEDIA_INDEX='pocketbookWildlifeMedia';
let pendingProfileMedia={};
function readProfileMedia(){try{const value=JSON.parse(localStorage.getItem(PROFILE_MEDIA_INDEX)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}catch{return{}}}
function writeProfileMedia(value){localStorage.setItem(PROFILE_MEDIA_INDEX,JSON.stringify(value))}
async function saveProfileMedia(scientific){const item=pendingProfileMedia[scientific],button=wildlifeProfile.querySelector('[data-save-profile-photo]');if(!item||!button||!('caches'in window))return;button.disabled=true;button.textContent='Saving photograph…';try{const response=await fetch(item.url,{mode:'no-cors',cache:'reload'});await(await caches.open(PROFILE_MEDIA_CACHE)).put(item.url,response);const index=readProfileMedia();index[scientific]={url:item.url,provider:item.provider,credit:item.credit,license:item.license,source:item.source,savedAt:new Date().toISOString()};writeProfileMedia(index);button.textContent='✓ Photograph saved offline';button.classList.add('saved');button.insertAdjacentHTML('afterend','<small class="profile-save-note">Attribution and source details were saved with this photograph.</small>')}catch(error){button.disabled=false;button.textContent='Retry saving photograph';button.insertAdjacentHTML('afterend','<small class="profile-save-note error">The photograph could not be saved. Check your connection and try again.</small>')}}
const observationGuides={
 Mammal:{identify:'Record overall size, body shape, coat pattern, horns or tusks, ear shape, tail and the way the animal moves.',behaviour:'Note whether it is alone, paired or in a group; record gait, posture, feeding, resting and interactions without approaching.',diet:'Record only food you actually see being eaten or handled. Browsing, grazing and scavenging can be confused from a brief view.',signs:'Look for tracks, dung, feeding remains, rubbed vegetation and paths, but do not identify sign from a single feature.',compare:'Compare body proportions, face, ears, tail, markings and movement with related species found in the same habitat.'},
 Bird:{identify:'Record size against a familiar object, bill shape, leg length, plumage pattern, flight silhouette and any clear call.',behaviour:'Note perch height, flight style, flock size, feeding method, display and association with water or mammals.',diet:'Record prey or plant material only when clearly observed; bill shape alone does not prove what an individual was eating.',signs:'Photograph feathers, nests or feeding remains without touching them or disturbing an occupied nest.',compare:'Compare bill, eye, legs, wing pattern, tail shape, call and habitat with similar birds; light can distort colour.'},
 Reptile:{identify:'From a safe distance record body proportions, head shape, scale pattern, colour, limbs and tail. Never handle an unknown reptile.',behaviour:'Note basking, shelter use, movement, defensive posture and proximity to water without provoking a response.',diet:'Record feeding only when directly observed. Do not approach a reptile or interfere with prey to obtain a better view.',signs:'Look for shed skin, tracks, slide marks, burrows and nesting traces; photograph in place and leave undisturbed.',compare:'Use several features—not colour alone—and obtain expert confirmation where venomous lookalikes are possible.'},
 Marine:{identify:'Record estimated length, body and fin shape, colour pattern, surfacing sequence and the position of any blow or dorsal fin.',behaviour:'Note group size, direction, dive interval, feeding, breaching and association with boats or other species.',diet:'Record prey only when clearly visible. Surface activity can have several explanations and should not be labelled as feeding automatically.',signs:'Log time, coordinates, water conditions, photographs and surfacing sequence; avoid collecting living animals or coral.',compare:'Compare silhouette, fin placement, markings, surfacing pattern and group behaviour; distance makes size estimates unreliable.'}
};
const speciesFieldGuides={
 'Gorilla beringei beringei':{identify:'Very large, powerfully built ape with long arms, a deep chest and black hair; mature males develop a broad silver-grey saddle across the back. The face, hands and feet are largely bare.',behaviour:'Lives in cohesive groups led by one or more adult males. Record feeding, resting, travel, play, grooming and vocal or chest-beating displays only from the distance set by guides.',diet:'Feeds mainly on leaves, shoots, stems and other plant material, with diet varying by place and season. Record the plant part actually handled rather than inferring food from nearby vegetation.',signs:'Large knuckle and foot impressions, bent or stripped vegetation, fibrous dung and temporary ground or tree nests. Ape nests and feeding traces overlap, so location and expert confirmation matter.',compare:'Eastern lowland gorilla is another form of eastern gorilla and cannot be separated safely by a brief field view alone. Chimpanzees are slighter, usually show less massive chests and make different nests and sign.'},
 'Gorilla gorilla gorilla':{identify:'Heavy forest ape with long arms, a broad chest and dark hair; adult males develop a silvery back and often a reddish crown. The face is comparatively broad with a pronounced brow.',behaviour:'Groups forage and rest in dense forest, while solitary males also occur. Note group composition, feeding height, nest use and vocalisations without following animals away from established viewing practice.',diet:'Takes fruit, leaves, stems and other plant foods, plus some invertebrate material. Record discarded fruit parts, chewed stems or directly observed feeding rather than assigning a food from habitat alone.',signs:'Knuckle prints, broad footprints, dung containing plant remains, broken stems and fresh day or night nests. Age sign by moisture and vegetation condition, but avoid touching it.',compare:'Other gorilla populations are best distinguished using geography and specialist evidence, not appearance alone. Chimpanzees are less massively built and their prints show different proportions.'},
 'Pan troglodytes':{identify:'Robust ape with long arms, dark hair and a bare face that varies with age and population. Adults lack a tail and often move by knuckle-walking, though they climb and walk upright for short distances.',behaviour:'Communities split into changing parties. Record pant-hoots, drumming, grooming, tool use, hunting or nesting without imitating calls, offering food or approaching.',diet:'Consumes fruit, leaves, seeds, insects and, at times, vertebrate prey. Only label an item when it is clearly seen or supported by diagnostic remains.',signs:'Knuckle and foot impressions, wadges of chewed plant fibre, cracked nuts or tool sites, dung with seeds and a new sleeping nest typically made each night. Do not enter or disturb nest sites.',compare:'Bonobos tend to be more gracile with longer-looking limbs and a darker face, but geography is essential. Gorillas are much heavier; baboons have tails and move as quadrupeds on palms rather than knuckles.'},
 'Pan paniscus':{identify:'Slender great ape with relatively long limbs, black hair, a dark face and hair that often parts centrally on the crown. There is no tail, and the body is generally less massive than a chimpanzee.',behaviour:'Lives in fluid communities with frequent social contact and changing foraging parties. Record posture, grooming, vocal exchanges, feeding and nest building without influencing movement.',diet:'Feeds heavily on fruit and also takes leaves, herbs, invertebrates and occasional vertebrate foods. Record direct evidence and avoid treating feeding ecology as identical at every site.',signs:'Knuckle and foot impressions, feeding remains, dung and constructed tree nests resemble chimpanzee evidence. Reliable separation normally requires location, repeated observation or expert analysis.',compare:'Chimpanzee is the principal look-alike; body build and facial impressions overlap. Bonobo identification must use verified locality together with multiple visible features.'},
 'Theropithecus gelada':{identify:'Large terrestrial primate with a short muzzle, a tufted tail and a conspicuous bare chest patch; adult males carry a long cape of hair over the shoulders. The fingers are adapted for precise grass picking.',behaviour:'Large multi-level bands spend much of the day sitting and feeding on open ground, then use cliffs as sleeping refuges. Note calls, lip displays, grooming and group spacing without blocking retreat routes.',diet:'Specialised largely for grasses, taking blades, seeds and underground parts, with other items varying seasonally. Record the plant part being selected rather than assuming every seated animal is feeding.',signs:'Narrow primate hand and foot prints, clipped grass patches, fibrous dung and well-used paths near feeding grounds or cliff roosts. Tracks alone do not distinguish it from baboons.',compare:'Hamadryas and other baboons have longer dog-like muzzles and lack the bare chest patch. Adult male geladas show the distinctive shoulder mantle and a shorter-looking muzzle.'},
 'Mandrillus sphinx':{identify:'Heavy forest monkey with a very short tail. Adult males have a massive head, blue-ridged muzzle, red nose and brightly coloured rump; females and young are smaller and much duller.',behaviour:'Forages on the forest floor in groups that may combine into very large aggregations. Record travel, digging, cheek-pouch use, grooming and threat displays without approaching feeding parties.',diet:'Takes fallen fruit, seeds, fungi, roots and animal matter. Note items placed in cheek pouches separately from items confirmed swallowed.',signs:'Hand and foot impressions, turned leaf litter, dug soil, opened hard fruits and dung containing seeds. Forest substrate often obscures tracks, and similar monkeys leave overlapping sign.',compare:'Drill lacks the adult male mandrill’s red-and-blue muzzle pattern. Baboons have longer tails and more uniformly dog-like faces; females and juveniles require locality and careful comparison.'},
 'Lemur catta':{identify:'Medium lemur with grey body, white face, dark eye patches and a long tail ringed boldly in black and white. It often holds the tail raised while moving on the ground.',behaviour:'Diurnal social groups travel both on the ground and in trees, sun-bask with limbs spread and use scent marking. Record group direction and alarm responses without surrounding animals.',diet:'Feeds on fruit, leaves, flowers and other plant parts, with opportunistic animal material. Record actual handling or ingestion and do not encourage close views with food.',signs:'Small hand-like prints, narrow paths, fruit remains, dung and scent-marking behaviour. The striped tail is more useful than spoor for confident field identification.',compare:'Other lemurs may share grey coats or facial masks but lack the complete black-and-white tail rings. Verreaux’s sifaka has a pale body, very long legs and distinctive sideways terrestrial hops.'},
 'Indri indri':{identify:'Large, virtually tailless lemur with long powerful hind limbs, rounded ears and variable black-and-white pelage. The small tail is unlike the long tails of most other lemurs.',behaviour:'Family groups move by strong vertical clinging and leaping and give far-carrying coordinated songs. Record song time, direction and group response without playback.',diet:'Feeds primarily on leaves with fruit, seeds and flowers also taken. Record the selected plant part; fallen fragments beneath a tree are not proof without observation.',signs:'Feeding fragments, dung, landing marks on soft ground and distinctive songs may reveal presence, while arboreal travel leaves little readable spoor.',compare:'Sifakas also cling and leap but possess long tails. Colour varies in indri, so tail length, proportions, voice and verified locality are more dependable than pelage alone.'},
 'Macaca sylvanus':{identify:'Sturdy, tailless macaque with yellowish-brown to grey fur, a pale or pinkish face and strong limbs. The tail is reduced to a small vestige rather than visibly projecting.',behaviour:'Multi-male, multi-female troops forage on the ground and in trees. Record grooming, infant carrying, feeding and alarm behaviour without offering food or drawing animals toward roads.',diet:'Omnivorous, taking leaves, roots, fruit, seeds and invertebrates according to season and site. Human food changes behaviour and must never be used as observation evidence.',signs:'Hand and foot prints, opened cones or fruit, dug ground, dung and sleeping-site use. Human-associated sign can be misleading where troops visit developed areas.',compare:'Baboons have long muzzles and visible tails. Other macaques are not native to Africa; the nearly tailless form and verified North African locality support identification.'},
 'Chlorocebus pygerythrus':{identify:'Slender grey-green monkey with a black face bordered by pale fur, pale underparts and a long tail. Adult males show distinctive blue and red genital colour when visible.',behaviour:'Active troops feed and travel on the ground and in trees, using distinct alarm calls and frequent social grooming. Observe from a distance, particularly around camps where food conditioning is possible.',diet:'Takes fruit, seeds, leaves, flowers and invertebrates, and may exploit crops or refuse. Record natural and human-derived foods separately.',signs:'Small hand and foot prints, fruit remains, dung and troop alarm calls. Similar guenons make comparable sign, so tracks alone rarely identify the species.',compare:'Tantalus, grivet and green monkeys are closely related and superficially similar. Face border, limb and tail colour plus verified geography should be checked together.'},
 'Colobus guereza':{identify:'Large black-and-white leaf monkey with a white facial fringe, white shoulder mantle and a long tail ending in a conspicuous white plume. The thumb is greatly reduced but seldom visible in the field.',behaviour:'Arboreal groups rest and feed in tree crowns and males give deep roaring calls. Record canopy route, leaps, group size and calls without playback or positioning beneath animals.',diet:'Feeds heavily on leaves, supplemented by fruit, seeds and flowers. Record the plant part directly; time spent in a fruiting tree does not alone establish feeding.',signs:'Dropped leaf or fruit fragments, dung beneath feeding or sleeping trees and resonant calls are common clues. Ground tracks are unusual and not a reliable survey method.',compare:'Angola colobus and other black-and-white colobus differ in the distribution and length of white fringes and tail hair. A clear photograph and locality are usually needed.'},
 'Erythrocebus patas':{identify:'Long-limbed, slender terrestrial monkey with reddish-brown upperparts, pale underparts, a pale moustache and a long tail. Adult males are substantially larger than females.',behaviour:'Fast-moving groups range widely through open country and often scan from raised ground or vegetation. Record route, spacing, vigilance and feeding without pursuit.',diet:'Takes gums, seeds, fruit, flowers and many invertebrates. Record the precise item or foraging action; rapid ground searching does not prove prey capture.',signs:'Small narrow primate prints, dug or disturbed soil, opened pods and dung along travel routes. Spoor can overlap with vervets and baboons.',compare:'Vervet monkeys are greyer, less long-limbed and more arboreal; patas shows a reddish back, pale face pattern and coursing build. Juveniles require extra caution.'},
 'Struthio camelus':{identify:'Very large flightless bird with a long bare neck, powerful legs and only two toes on each foot. Adult males are mainly black and white; females and young birds are greyer brown.',behaviour:'Record walking, running, dust bathing, courtship and nest attendance from a distance. Adults guarding eggs or chicks can defend forcefully.',diet:'Takes seeds, leaves, flowers, fruit and small animal matter. Record swallowed items only when visible; ground pecking alone is not diagnostic.',signs:'Large two-toed footprints, shallow nest scrapes, substantial droppings and eggshell fragments. Do not collect material at protected or archaeological sites.',compare:'Somali ostrich may show different skin colour and occurs mainly in northeastern Africa; location and specialist references are needed where identification is uncertain.'},
 'Sagittarius serpentarius':{identify:'Very tall terrestrial raptor with long bare legs, grey body, black flight feathers and tail, red-orange facial skin and a crest of elongated dark feathers.',behaviour:'Usually walks through open country while searching for prey, sometimes in pairs. Record deliberate stepping, stamping, short pursuit and soaring without forcing flight.',diet:'Takes insects and small vertebrates, including reptiles. Record prey directly; it is not exclusively a snake hunter.',signs:'Large walking tracks, pellets, feathers and substantial stick nests in flat-topped trees. Tracks alone are difficult to separate from other large ground birds.',compare:'Cranes and bustards lack the hooked raptor bill and red facial skin. In flight, long legs project behind and elongated central tail feathers are visible.'},
 'Haliaeetus vocifer':{identify:'Large, heavy eagle with a white head, breast and tail contrasting with chestnut body and dark wings. Adults have a yellow face and strongly hooked bill; juveniles are mottled brown.',behaviour:'Often perches conspicuously beside water and calls in pairs. Record fishing attempts, piracy from other birds, territorial calling and perch use without approaching nests.',diet:'Frequently takes fish but also captures birds and other available prey or scavenges. Record the item directly rather than assuming every water-side strike caught fish.',signs:'Fish remains, pellets, whitewash beneath favourite perches and large stick nests near water. These signs are not exclusive to this eagle.',compare:'Palm-nut vulture has extensive white plumage but different wing pattern and bare facial skin. Juvenile fish eagles require comparison with other large brown eagles.'},
 'Polemaetus bellicosus':{identify:'Very large eagle with dark brown head and upperparts, pale underparts marked with dark spots, long broad wings and a short barred tail. Juveniles are much paler.',behaviour:'Often soars high or watches from exposed perches. Record hunting approach, prey response and nest activity from far enough away to avoid disturbance.',diet:'Takes a wide range of birds, reptiles and mammals. Identify prey only from direct observation or diagnostic remains.',signs:'Large stick nests in tall trees or structures, pellets, feathers and prey remains. Nest occupation must be confirmed without close approach.',compare:'Crowned eagle has shorter, broader wings and is more forest-associated; Verreaux’s eagle is mostly black with a white back marking. Juveniles demand extra caution.'},
 'Terathopius ecaudatus':{identify:'Distinctive short-tailed eagle with very long wings, black body, chestnut mantle, grey shoulder patches and bright red face and feet in adults. Sexes differ in wing pattern.',behaviour:'Spends long periods in low rocking flight with wings held slightly raised. Record flight direction, searches, display and scavenging without using colour alone at distance.',diet:'Takes small vertebrates, carrion and other animal material. Record the item directly; circling over a carcass does not prove feeding.',signs:'Large stick nest, pellets, feathers and remains near perches, though ground evidence is rarely diagnostic.',compare:'Short tail and rocking flight distinguish adults from most eagles. Juveniles are brown and can resemble snake-eagles or other immature raptors.'},
 'Ephippiorhynchus senegalensis':{identify:'Enormous black-and-white stork with a long red-and-black bill crossed by a yellow frontal saddle. Adults have long dark legs; eye colour differs between sexes.',behaviour:'Usually walks slowly through shallow wetlands alone or in pairs. Record probing, striking, territorial display and flight without entering feeding shallows.',diet:'Takes fish, frogs, reptiles, crustaceans and other aquatic prey. Record captured prey when visible rather than inferring from bill movements.',signs:'Large long-toed tracks in mud, feeding probes and a substantial stick nest in a tall tree. Similar wetland birds can leave overlapping spoor.',compare:'Woolly-necked stork is much smaller with a pale neck; black stork lacks the saddle-shaped bill marking. Jabiru does not occur naturally in Africa.'},
 'Bucorvus leadbeateri':{identify:'Huge ground-dwelling hornbill with black plumage, white primary feathers visible in flight and bare red facial and throat skin in adults. Females show a violet-blue throat patch.',behaviour:'Family groups walk and forage together and give deep booming calls. Record group size, cooperative feeding and roost movement without approaching nest cavities.',diet:'Takes insects and other small animals, plus occasional plant material. Record prey directly because searching and handling can obscure the item.',signs:'Large four-toed walking tracks, pellets, feathers and large tree cavities used for nesting. Do not inspect or touch active cavities.',compare:'Abyssinian ground hornbill occurs mainly farther north and has blue facial areas; flying birds can resemble large dark storks until the white primaries show.'},
 'Coracias caudatus':{identify:'Stocky roller with lilac breast, turquoise belly and wing panels, greenish head, rufous face and elongated outer tail feathers in adults. Colours change strongly with light.',behaviour:'Often watches from exposed perches before dropping to the ground for prey. Record perch choice, rolling display, prey capture and territorial calls.',diet:'Takes insects and small vertebrates. Record visible prey; repeated ground drops do not identify the food item.',signs:'Pellets and insect remains may occur beneath favoured perches; nests are in tree cavities. Neither sign should be assigned without direct association.',compare:'Lilac-throated roller has different head and breast pattern and a more restricted western distribution. European roller lacks the lilac breast and tail streamers.'},
 'Balaeniceps rex':{identify:'Very large grey wetland bird with exceptionally broad shoe-shaped bill, long legs, a slight rear crest and an intense pale-eyed stare. It often stands motionless.',behaviour:'Usually solitary in dense swamp vegetation. Record prolonged stillness, slow steps, lunging strikes and bill-clattering from a respectful distance.',diet:'Takes fish and other wetland vertebrates. Record prey only when visible; an unsuccessful strike should not be assigned a target.',signs:'Very large long-toed tracks, flattened vegetation, droppings and broad nests on wetland vegetation. Avoid entering nesting habitat.',compare:'Pelicans have a flexible pouch and different posture; hamerkop is far smaller and brown. From behind, bill size and head profile remain important.'},
 'Phoenicopterus roseus':{identify:'Very tall pale pink-and-white flamingo with a pink bill ending in black, long pink legs and crimson-and-black wings visible in flight.',behaviour:'Forms flocks that feed by sweeping an inverted bill through water. Record flock movement, display, flight lines and disturbance without approaching breeding concentrations.',diet:'Filters small aquatic organisms and plant material. Record feeding method and water conditions rather than claiming a specific food without sampling evidence.',signs:'Webbed footprints, parallel feeding traces in soft substrate, feathers and mud nest mounds at colonies. Breeding sites are highly disturbance-sensitive.',compare:'Lesser flamingo is smaller and usually deeper pink, with a much darker bill. Size is difficult at distance, so bill pattern and mixed-flock comparison help.'},
 'Ardeotis kori':{identify:'Massive ground bird with long legs, mottled brown-grey body, barred neck and a small crested head. Males are substantially larger and can inflate the neck in display.',behaviour:'Walks slowly through open country and usually flies only when necessary. Record foraging, vigilance and courtship without driving the bird into flight.',diet:'Omnivorous, taking insects, small vertebrates and plant material. Record visible items; pecking alone does not establish diet.',signs:'Large three-toed tracks, droppings, dust-bathing scrapes, feathers and shallow ground nests. Avoid approaching a sitting bird.',compare:'Denham’s bustard is smaller and shows different neck and wing pattern. Female kori bustards can overlap large bustards in apparent size at distance.'},
 'Rynchops flavirostris':{identify:'Long-winged river bird with black upperparts, white underparts and a bright bill whose lower mandible projects beyond the upper. The short legs are red.',behaviour:'Feeds by flying low over calm water with the lower bill cutting the surface. Record feeding lines, flock roosts and breeding activity without approaching sandbanks.',diet:'Takes small fish and aquatic prey encountered while skimming. Record captures only when visible; surface contact does not always mean success.',signs:'Three-toed tracks, shallow nest scrapes and colonies on exposed sandbanks. Human footprints or boat landings near colonies indicate disturbance risk.',compare:'Terns have equal bill mandibles and usually plunge-dive rather than skim continuously. At rest, the unique lower mandible is diagnostic when visible.'},
 'Aepyceros melampus':{identify:'Medium-sized, lightly built antelope with a reddish-brown back, pale underside and black markings on the rump, tail and rear legs. Only males carry long lyre-shaped horns.',behaviour:'Forms female herds, bachelor groups and territorial associations that change with season and conditions. Record alarm snorts, high leaps, grooming and habitat-edge use.',diet:'A flexible mixed feeder that grazes and browses. Record the plant part actually taken before describing the feeding mode.',signs:'Small pointed cloven tracks, pellet dung, browsed or grazed vegetation, resting forms and repeated paths between cover and water.',compare:'Springbok has a white face, dark flank stripe and dorsal fan. Puku and lechwe lack the impala’s black rump and heel markings.'},
 'Tragelaphus strepsiceros':{identify:'Large, long-legged antelope with narrow white body stripes, very large ears and a pale facial chevron. Adult males carry long spiral horns and a shaggy throat fringe.',behaviour:'Usually seen singly or in small loose groups. Record browsing, stillness in cover, alarm barking and male displays without driving animals from thickets.',diet:'Browses leaves, shoots, herbs, pods and fruit. Record plant use directly because feeding varies with habitat and season.',signs:'Large narrow cloven tracks with pointed tips, sizeable pellet dung, browsed shrubs, beds in cover and trails through thickets.',compare:'Lesser kudu is smaller with more body stripes. Nyala shows stronger sexual colour differences and males have shaggier coats and yellow lower legs.'},
 'Connochaetes taurinus':{identify:'Large antelope with heavy forequarters, sloping back, broad muzzle, dark vertical shoulder bars, curved horns in both sexes and a long dark tail.',behaviour:'Occurs in herds of changing size. Record grazing, rutting, calf groups, river approaches and coordinated movement without blocking travel routes.',diet:'Mainly grazes short and medium grasses. Record feeding height and habitat rather than inferring a grass species.',signs:'Broad cloven tracks, abundant dung in herd areas, trampled routes and grazing lawns. Mixed herds can make attribution difficult.',compare:'Black wildebeest has a pale horse-like tail, forward-curving horn tips and a more uniformly dark body. Buffalo is heavier with broader horn bases.'},
 'Hippotragus niger':{identify:'Large, powerfully built antelope with long ringed horns sweeping backward, a stiff upright mane and bold black-and-white facial pattern. Adult males are usually darkest.',behaviour:'Commonly forms female-and-young groups led by a territorial male, with bachelor groups elsewhere. Record group structure, vigilance and access to water from a distance.',diet:'Predominantly grazes medium-to-tall grasses and may browse occasionally. Record the vegetation actually cropped.',signs:'Large rounded cloven tracks, substantial pellet dung, grazed patches, beds and paths linking woodland, grass and water.',compare:'Roan antelope is generally paler, has a darker facial mask with white eyebrows and less strongly contrasting body colour. Horn shape overlaps.'},
 'Hippotragus equinus':{identify:'Very large antelope with a grey-brown to reddish coat, black-and-white face, long ears with dark tufts and strongly ringed horns curving backward.',behaviour:'Usually in small herds with a dominant male or in bachelor groups. Note alert posture, grazing, resting shade and water visits without cutting off escape routes.',diet:'Primarily grazes grasses but may browse. Direct feeding observations are more reliable than habitat-based assumptions.',signs:'Large cloven tracks, pellet dung, grazing traces, resting sites and regular trails near water.',compare:'Sable antelope is typically darker and has a more sharply contrasted pale face. Female sable can resemble roan, so face, ear and coat characters should be combined.'},
 'Taurotragus oryx':{identify:'Africa’s largest antelope, heavy-bodied yet long-legged, with a tan to grey coat, shoulder hump, throat dewlap and tightly spiralled horns in both sexes.',behaviour:'Occurs singly or in herds that can become large. Record group composition, clicking movement, browsing height and calf position without compressing the herd.',diet:'A mixed feeder taking leaves, shoots, fruit and grasses. Record visible plant use rather than assigning diet from spoor alone.',signs:'Very large rounded cloven tracks, sizeable pellet dung, high browsing, resting depressions and broad herd paths.',compare:'Greater kudu is more slender, has prominent white stripes and males carry wider open spirals. Domestic cattle have different horn structure and human association.'},
 'Antidorcas marsupialis':{identify:'Small-to-medium gazelle-like antelope with a white face, dark side stripe, white belly and a folded white dorsal fan that can open during display. Both sexes carry ringed horns.',behaviour:'Forms flexible herds and may perform high stiff-legged leaps. Record pronking, territorial marking, grazing and group movement without provoking flight.',diet:'Grazes and browses, including moisture-rich plants in dry areas. Record the plant material actually taken.',signs:'Small narrow cloven tracks, pellet dung, short grazing and territorial dung or urine marks.',compare:'Impala lacks the broad dark flank stripe and white dorsal fan. Thomson’s gazelle has a different facial pattern and occurs mainly farther north and east.'},
 'Oryx gazella':{identify:'Large desert-adapted antelope with very long straight horns, grey-fawn body, black-and-white face, dark flank markings and black upper legs.',behaviour:'Often travels in groups across open dry country. Record shade use, digging, feeding and herd spacing without pursuing animals in heat.',diet:'Feeds on grasses, herbs, roots, bulbs and browse according to conditions. Record direct use, particularly excavated foods.',signs:'Large pointed cloven tracks, pellet dung, excavations for roots or bulbs, resting scrapes and long travel lines.',compare:'East African oryx has different flank and leg patterning and occurs farther northeast. Addax is paler with spiralled horns and does not naturally overlap most gemsbok range.'},
 'Kobus ellipsiprymnus':{identify:'Large shaggy antelope with a grey-brown coat, pale eye and muzzle markings and heavily ringed horns in males. Common waterbuck shows a white rump ring; defassa form has a solid white rump patch.',behaviour:'Often remains near dependable water but may feed some distance away. Record territorial males, female groups, resting and water use.',diet:'Predominantly grazes grasses and may take other vegetation. Record grass height and plant parts when feeding is visible.',signs:'Large splayed cloven tracks, coarse pellet dung, grazed areas and paths connecting cover, feeding areas and water.',compare:'Puku and lechwe are smaller and less shaggy. Rump pattern separates common and defassa forms but should not be used to infer precise boundaries.'},
 'Kobus leche':{identify:'Medium-sized wetland antelope with elongated spreading hooves, reddish to tawny coat and pale underparts. Males carry long ridged horns; lower legs often show dark markings.',behaviour:'Closely associated with floodplains and shallow water. Record herd structure, territorial activity and movement through water without forcing crossings.',diet:'Grazes floodplain and aquatic-edge grasses. Record water depth and the vegetation cropped when observable.',signs:'Elongated splayed hoofprints in soft mud, pellet dung, trampled wetland paths and cropped floodplain grasses.',compare:'Puku is more uniformly golden and less specialised for deep wet ground. Nile lechwe is darker and has different markings; location and sex matter.'},

 'Acinonyx jubatus':{identify:'Tall, lightly built cat with long legs, a small rounded head, solid black spots and dark tear marks from each eye toward the mouth. The long tail is usually ringed near its tip.',behaviour:'Often scans from raised ground. Females are commonly solitary except with cubs; males may form coalitions. Never pressure a resting animal or interfere with a pursuit.',diet:'Primarily hunts small-to-medium antelope and other vertebrates. Record prey only when directly seen; presence beside a carcass does not prove the cheetah made the kill.',signs:'Compact cat tracks may show claw tips because the claws are less retractile. Scat and scent marks can occur on prominent trees, mounds or other landmarks.',compare:'Leopard is heavier, has rosettes instead of solid spots and lacks tear marks. Serval has much larger ears, a shorter tail and proportionally longer legs.'},
 'Lycaon pictus':{identify:'Long-legged canid with very large rounded ears, a white-tipped tail and an individually unique patchwork coat of black, tan, brown and white.',behaviour:'Highly social packs rest, greet, rally and travel together. Record pack size, pups and coordinated movement without separating animals or following a hunt closely.',diet:'Packs hunt medium-sized antelope and other vertebrate prey. Record directly observed prey; feeding is rapid and carcass evidence can disappear quickly.',signs:'Dog-like four-toed tracks with visible claws, communal resting sites, scattered scat and well-used travel routes. Domestic dog tracks require careful exclusion.',compare:'Spotted hyena has a sloping back and rounded ears. Jackals are much smaller and lack the irregular multicoloured coat.'},
 'Crocuta crocuta':{identify:'Powerful carnivore with rounded ears, broad muzzle, high shoulders and a back sloping toward shorter hindquarters. The sandy to grey-brown coat has irregular dark spots.',behaviour:'Lives in complex clans but may travel alone. Record greeting, whooping, scent marking and den activity without approaching cubs or feeding animals.',diet:'Both hunts and scavenges. Direct observation is required before assigning a kill; pale fragmented dung can reflect consumption of bone.',signs:'Broad four-toed tracks usually show claws; foreprints are larger than hindprints. Look for pale bone-rich scat, latrines, hair and dens.',compare:'Brown hyena has long shaggy dark fur and striped legs. African wild dog has huge ears, a patchwork coat and more even body proportions.'},
 'Giraffa camelopardalis':{identify:'Extremely tall browser with a long neck and legs, sloping back, horn-like ossicones and a patterned coat. Pattern and lower-leg markings vary among populations.',behaviour:'Loose groups change composition frequently. Record browsing height, vigilance, necking, calf position and drinking posture while leaving water access clear.',diet:'Browses leaves, shoots, flowers and pods. Record the plant and feeding height only when visible rather than assuming acacia use.',signs:'Very large divided hoofprints, high browse lines, stripped twig tips, pellet dung and long-stride pathways.',compare:'No other living African mammal shares its height. Coat pattern alone should not assign a giraffe species or subspecies without geographic and expert support.'},
 'Hippopotamus amphibius':{identify:'Massive semi-aquatic mammal with barrel-shaped body, very short legs, broad muzzle and eyes, ears and nostrils set high on the head.',behaviour:'Usually rests in water by day and travels onto land to feed, often after dark. Treat water edges and paths as high-risk and never stand between a hippo and water.',diet:'Primarily grazes grasses on land. Aquatic resting does not mean aquatic plants are its principal food.',signs:'Four-toed tracks, broad paths between water and grazing, clipped grass and dung spread by tail-fanning. Fresh paths may be active at night.',compare:'Pygmy hippopotamus is much smaller, more solitary and associated with dense forest and swamp habitat.'},
 'Equus quagga':{identify:'Stocky horse-shaped grazer with bold black-and-white striping, upright mane and tufted tail. Each individual pattern differs.',behaviour:'Often forms stable family groups within larger herds. Record grooming, vigilance, stallion herding, dust bathing and association with other grazers.',diet:'Predominantly grazes grasses and can crop coarser growth. Record bite height and vegetation only when clearly observed.',signs:'Single-hoof tracks, fibrous dung, grazing lawns, dust baths and trails to water. Tracks overlap domestic horses and donkeys.',compare:'Grévy’s zebra has narrower stripes, a white belly and very large rounded ears. Mountain zebra has a grid-like rump pattern and throat dewlap.'},
 'Phacochoerus africanus':{identify:'Robust pig with broad flattened head, facial warts, upward-curving tusks, sparse mane and a tail held upright while running. Adults often kneel to graze.',behaviour:'Family groups commonly feed together; males may be solitary. Record kneeling, rooting, wallowing and reverse entry into burrows without crowding occupied holes.',diet:'Mostly grazes but also takes roots, bulbs and fruit. Disturbed soil alone does not establish what was eaten.',signs:'Rounded two-toed tracks often show dewclaws in soft ground, rooted soil, dung, wallows and burrows modified from aardvark holes.',compare:'Bushpig is hairier, usually darker, has a longer facial profile and lacks the same prominent facial warts and upright running tail.'},
 'Crocodylus niloticus':{identify:'Large crocodilian with a broad robust snout, heavily armoured back and powerful tail. Colour varies from olive to dark grey-brown.',behaviour:'Basks at water margins and floats with eyes and nostrils exposed. Keep well back from every shoreline and never approach nests or young.',diet:'An opportunistic predator taking aquatic and terrestrial animals. A submerged or floating animal is not proof of hunting.',signs:'Five-toed foreprints, four-toed hindprints, belly or tail drags, slides, basking marks and nests above the waterline.',compare:'West African crocodile is externally very similar and identification depends heavily on geography and expert assessment; slender-snouted crocodiles have a much narrower snout.'},

 'Loxodonta africana':{identify:'Very large body, pillar-like legs, deeply concave back, huge fan-shaped ears and two finger-like projections at the trunk tip. Tusks vary and are not a safe basis for sexing.',behaviour:'Watch family groups led by experienced females, adult bulls alone or in loose associations, trunk contact, ear position, dust bathing and access to water. Give every elephant an escape route.',diet:'A mixed feeder that takes grasses, leaves, bark, roots and fruit. Record the plant part actually handled rather than inferring diet from damaged vegetation.',signs:'Large round foreprints, more oval hindprints, fibrous dung, stripped bark, broken branches, dusting sites and well-used paths. Fresh sign means elephants may be close.',compare:'African forest elephant is generally smaller with rounder ears and straighter, downward-pointing tusks; the two should be separated with range and expert evidence, not size alone.'},
 'Panthera leo':{identify:'Large, powerfully built cat with a plain tawny coat, rounded ears and a black-tufted tail. Adult males often have a mane; females and young males may not.',behaviour:'Record group composition, resting, social greeting, scent marking, roaring and hunting attempts. Lions rest for long periods, so time and repeated observation matter.',diet:'Primarily hunts medium-to-large mammals and also scavenges. Identify prey only from direct observation or diagnostic remains; avoid assuming every carcass was killed by lions.',signs:'Broad rounded tracks usually without claw marks, three-lobed rear pad, scrapes, scent marks, hair and large segmented scat. Tracks alone do not establish pride size.',compare:'Leopard is smaller and rosetted; cheetah is slender with solid spots and facial tear marks. A lioness at distance can be confused with a large plain-coloured cat without scale.'},
 'Panthera pardus':{identify:'Muscular cat with a long tail and dark rosettes rather than solid spots. The face and lower legs carry smaller solid markings; coat colour varies with habitat and light.',behaviour:'Usually encountered alone. Note stalking, scent marking, tree use, alarm calls from prey and whether food has been moved or cached. Do not approach a resting leopard.',diet:'An adaptable predator taking prey from small vertebrates to antelope, and sometimes scavenging. Record prey remains cautiously because other predators may use the same carcass.',signs:'Round tracks with four toes and usually no claw marks, scrapes, scat placed along routes, claw marks and cached prey. Front tracks are broader than hind tracks.',compare:'Cheetah has solid spots, a smaller head, long legs and dark tear marks; jaguar does not occur wild in Africa. Spotted hyena has a dog-like print with visible claws.'},
 'Syncerus caffer':{identify:'Heavy bovine with dark coat, broad muzzle and thick horns. Mature bulls may develop a fused horn boss; females and younger animals have lighter, less massive horns.',behaviour:'Observe herd spacing, calves, bachelor bulls, wallowing and alert posture. Solitary bulls and animals hidden in dense cover require exceptional distance and care.',diet:'Predominantly grazes grasses and depends on regular water in many landscapes. Record grazing height and habitat rather than attributing a specific grass species without confirmation.',signs:'Large cloven hoofprints with rounded toes, flattened grazing lawns, dung pats, mud wallows and rubbed vegetation. Tracks can overlap cattle; context and measurements help.',compare:'Domestic cattle vary greatly but often show human association or branding. Eland is taller and more lightly built, with spiral horns and a different track shape.'},
 'Diceros bicornis':{identify:'Two-horned rhinoceros with a pointed, prehensile upper lip adapted for browsing. Head carriage is relatively high; horn size and shape are individually variable.',behaviour:'Often solitary except for mothers with calves and temporary associations. Note browsing, dung middens, urine spraying and ear position from a very safe distance.',diet:'Browses woody plants, shrubs and herbs, using the hooked lip to grasp stems. Record clipped twigs or directly observed feeding; plant identification needs care.',signs:'Three-toed tracks, large dung middens containing woody fragments, broken browse, rubbed posts and well-used paths. Never follow fresh sign on foot without a qualified guide.',compare:'White rhinoceros has a broad square grazing lip, generally lower head carriage and a different feeding posture. Horns alone cannot reliably separate the species.'},
 'Ceratotherium simum':{identify:'Very large rhinoceros with a broad square upper lip, long head and pronounced shoulder hump. It commonly carries the head low while grazing.',behaviour:'May occur alone or in small associations; territorial bulls use dung middens and urine marking. Record resting, grazing and social spacing without altering its movement.',diet:'A specialised grazer using the broad lips to crop short grasses. Record feeding posture and grass height rather than inferring a particular plant species.',signs:'Three-toed tracks, broad grazing paths, dung middens with finely cut grass, wallows and rubbing posts. Fresh sign warrants distance and professional guidance.',compare:'Black rhinoceros has a pointed hooked browsing lip and commonly holds the head higher. Body size, colour and horn length overlap and are unreliable on their own.'}
};
function observationCards(row){const guide=speciesFieldGuides[row?.[1]]||observationGuides[row?.[2]]||observationGuides.Mammal,specific=!!speciesFieldGuides[row?.[1]];return `<div class="field-guide-status">${specific?'Species-specific offline field notes':'Group-level observation framework'}</div><div class="observation-grid"><article><small>LOOK</small><strong>Identification</strong><p>${guide.identify}</p></article><article><small>WATCH</small><strong>Behaviour</strong><p>${guide.behaviour}</p></article><article><small>FEEDING</small><strong>Diet evidence</strong><p>${guide.diet}</p></article><article><small>TRACE</small><strong>Tracks & signs</strong><p>${guide.signs}</p></article><article><small>CHECK</small><strong>Similar species</strong><p>${guide.compare}</p></article></div>`}
function commonsValue(value){return String(value?.value||value||'').replace(/<[^>]*>/g,'').trim()}
function audioPanel(name,scientific){const file=window.pocketWildlifeSounds?.[name],url=file?`https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(file)}`:'';return `<section class="profile-section audio-field-section"><div class="entry-kicker">SOUNDS</div><h3>Listen and compare</h3>${file?`<div class="verified-audio"><strong>Connected reference recording</strong><audio controls preload="none" src="${profileSafe(url)}">Audio playback is unavailable.</audio><a href="https://commons.wikimedia.org/wiki/File:${encodeURIComponent(file)}" target="_blank" rel="noopener">Recording source and licence ↗</a></div>`:`<p>No recording has been manually connected to this species yet.</p>`}<button class="find-audio" type="button" data-find-audio="${profileSafe(scientific)}" data-audio-name="${profileSafe(name)}">Search licensed Commons recordings</button><div class="audio-search-results" aria-live="polite"></div><p class="profile-caution">Search results are matching audio files, not automatically verified animal calls. Read each title and source page before using a recording for identification.</p></section>`}
async function findCommonsAudio(button){const box=button.parentElement.querySelector('.audio-search-results'),scientific=button.dataset.findAudio,name=button.dataset.audioName;button.disabled=true;button.textContent='Searching recordings…';box.innerHTML='<p>Checking Wikimedia Commons audio metadata…</p>';try{const query=`${scientific} ${name} sound`,url=`https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=${encodeURIComponent(query)}&gsrnamespace=6&gsrlimit=12&prop=imageinfo&iiprop=url|mime|extmetadata&format=json&origin=*`,data=await profileJson(url),pages=Object.values(data.query?.pages||{}),audio=pages.map(page=>({page,info:page.imageinfo?.[0]})).filter(item=>item.info?.url&&String(item.info.mime).startsWith('audio/')).slice(0,5);box.innerHTML=audio.length?audio.map(({page,info})=>{const meta=info.extmetadata||{},title=String(page.title||'').replace(/^File:/,''),creator=commonsValue(meta.Artist)||commonsValue(meta.Credit)||'Contributor not supplied',license=commonsValue(meta.LicenseShortName)||commonsValue(meta.UsageTerms)||'Licence not supplied',source=`https://commons.wikimedia.org/wiki/${encodeURIComponent(page.title)}`;return `<article class="audio-result"><strong>${profileSafe(title)}</strong><audio controls preload="none" src="${profileSafe(info.url)}">Audio playback is unavailable.</audio><small>${profileSafe(creator)} · ${profileSafe(license)}</small><a href="${profileSafe(source)}" target="_blank" rel="noopener">Check description and licence ↗</a></article>`}).join(''):'<div class="profile-unavailable">No matching Commons audio was returned. This does not mean that no recording exists.</div>'}catch(error){box.innerHTML='<div class="profile-unavailable">The recording service is unavailable. Existing connected calls and the offline field guide still work.</div>'}finally{button.disabled=false;button.textContent='Search again'}}
async function openWildlifeProfile(scientific){
 const row=(window.pocketWildlife||[]).find(animal=>animal[1]===scientific),name=row?.[0]||scientific,page=row?.[4]||scientific,checked=new Date(),savedPhoto=readProfileMedia()[scientific];
 wildlifeDialog.showModal();wildlifeProfile.innerHTML='<p class="database-status">Building sourced field entry…</p>';
 const [taxonResult,summaryResult]=await Promise.allSettled([profileJson(`https://api.gbif.org/v1/species/match?name=${encodeURIComponent(scientific)}`),profileJson(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(page)}`)]),taxon=taxonResult.status==='fulfilled'?taxonResult.value:null,summary=summaryResult.status==='fulfilled'?summaryResult.value:null,key=taxon?.usageKey||taxon?.speciesKey;
 let occurrence=null;if(key){try{occurrence=await profileJson(`https://api.gbif.org/v1/occurrence/search?taxon_key=${key}&limit=0&facet=country&facetLimit=12`)}catch{}}
 let mediaRecord=null;if(key){try{const mediaData=await profileJson(`https://api.gbif.org/v1/occurrence/search?taxon_key=${key}&media_type=StillImage&limit=20`);mediaRecord=mediaData.results?.find(item=>(item.media||[]).some(mediaItem=>mediaItem.identifier))||null}catch{}}
 const media=mediaRecord?.media?.find(item=>item.identifier),countries=(occurrence?.facets?.find(facet=>String(facet.field).toLowerCase()==='country')?.counts||[]).map(item=>({name:countryName(item.name),count:item.count})),classification=[['Kingdom',taxon?.kingdom],['Phylum',taxon?.phylum],['Class',taxon?.class],['Order',taxon?.order],['Family',taxon?.family],['Genus',taxon?.genus]].filter(item=>item[1]),photo=savedPhoto?.url||media?.identifier||summary?.originalimage?.source||summary?.thumbnail?.source,photoProvider=savedPhoto?.provider||(media?'GBIF occurrence media':'Wikimedia reference'),photoCredit=savedPhoto?.credit||media?.creator||media?.rightsHolder||mediaRecord?.institutionCode||'Contributor not supplied',photoLicense=savedPhoto?.license||media?.license||media?.rights||'Licence not supplied',photoSource=savedPhoto?.source||(mediaRecord?.key?`https://www.gbif.org/occurrence/${mediaRecord.key}`:summary?.content_urls?.desktop?.page);
 if(photo)pendingProfileMedia[scientific]={url:photo,provider:photoProvider,credit:photoCredit,license:photoLicense,source:photoSource||''};
 wildlifeProfile.innerHTML=`<div class="wildlife-profile-hero">${photo?`<img src="${profileSafe(photo)}" alt="${profileSafe(name)} photograph">`:'<div class="profile-photo-missing">Photograph unavailable offline</div>'}<div><p class="eyebrow">FIELD ENTRY</p><h2>${profileSafe(name)}</h2><em>${profileSafe(scientific)}</em><span>${profileSafe(row?.[2])}</span></div></div><section class="profile-section"><div class="entry-kicker">IDENTIFICATION CONTEXT</div><h3>About this species</h3><p>${profileSafe(summary?.extract,'A connected descriptive account is unavailable. The offline field notes below remain available.')}</p><div class="profile-habitat"><small>Pocketbook habitat index</small><strong>${profileSafe(row?.[3])}</strong></div><p class="profile-caution">Similar species, age, sex and local variation can cause mistakes.</p></section><section class="profile-section field-craft-section"><div class="entry-kicker">FIELD CRAFT · WORKS OFFLINE</div><h3>Identification, behaviour and sign</h3>${observationCards(row)}<p class="profile-caution">Use several features, keep a safe distance and confirm uncertain identifications with a qualified guide.</p><button class="profile-record" type="button" data-record-animal="${profileSafe(name)}">＋ Record this sighting</button></section>${audioPanel(name,scientific)}<section class="profile-section"><div class="entry-kicker">TAXONOMY</div><h3>Scientific classification</h3>${classification.length?`<div class="classification-grid">${classification.map(([rank,value])=>`<div><small>${rank}</small><strong>${profileSafe(value)}</strong></div>`).join('')}</div>`:'<div class="profile-unavailable">GBIF taxonomy could not be retrieved. The offline scientific name remains available.</div>'}</section><section class="profile-section"><div class="entry-kicker">OCCURRENCE EVIDENCE</div><h3>Countries represented in GBIF records</h3>${countries.length?`<div class="occurrence-list">${countries.map(country=>`<span><strong>${profileSafe(country.name)}</strong><small>${Number(country.count).toLocaleString()} records</small></span>`).join('')}</div><p class="profile-caution">These are database records, not a complete present-day range map.</p>`:'<div class="profile-unavailable">Recorded-country evidence is unavailable offline or was not returned.</div>'}</section><section class="profile-section"><div class="entry-kicker">CONSERVATION</div><h3>Check current status</h3><p>Open the authoritative assessment to confirm the current category and publication date.</p><div class="profile-links">${key?`<a href="https://www.gbif.org/species/${key}" target="_blank" rel="noopener">GBIF taxon entry ↗</a>`:''}<a href="https://www.iucnredlist.org/search?query=${encodeURIComponent(scientific)}&searchType=species" target="_blank" rel="noopener">IUCN Red List search ↗</a></div></section><div class="profile-sources"><strong>Sources checked ${checked.toLocaleString()}</strong><span>GBIF: taxonomy and occurrence evidence</span><span>Wikipedia/Wikimedia: descriptive reference and media</span><span>Wikimedia Commons: audio metadata and licences</span><small>Local guides and current conservation authorities remain essential.</small></div>`;
 if(photo){const hero=wildlifeProfile.querySelector('.wildlife-profile-hero');hero?.insertAdjacentHTML('afterend',`<div class="profile-media-credit"><strong>${savedPhoto?'Saved offline · ':''}${profileSafe(photoProvider)}</strong><span>${profileSafe(photoCredit)} · ${profileSafe(photoLicense)}</span>${photoSource?`<a href="${profileSafe(photoSource)}" target="_blank" rel="noopener">Open media record ↗</a>`:''}</div><div class="profile-media-save"><button type="button" data-save-profile-photo="${profileSafe(scientific)}" ${savedPhoto||!('caches'in window)?'disabled':''}>${savedPhoto?'✓ Photograph saved offline':('caches'in window?'Save photograph for offline use':'Offline photo saving unavailable')}</button>${savedPhoto?`<small>Saved ${profileSafe(new Date(savedPhoto.savedAt).toLocaleDateString())}. Attribution remains attached.</small>`:'<small>Saves this exact sourced photograph on this device. Availability depends on the provider permitting download.</small>'}</div>`)}
}
wildlifeDialog.addEventListener('click',event=>{const audio=event.target.closest('[data-find-audio]');if(audio){findCommonsAudio(audio);return}const save=event.target.closest('[data-save-profile-photo]');if(save){saveProfileMedia(save.dataset.saveProfilePhoto);return}if(event.target.closest('[data-record-animal]'))wildlifeDialog.close()});
